NS_IMETHODIMP ExchangeMessageCopyHandler::EndMove(bool aMoveSucceeded) {
  // We handle move success/failure in `OnCreateFinished` so that we don't
  // delete the message until we know the message has been created in the
  // destination folder. The only caller of `EndMove` seems to be
  // `CopyMessageStreamListener::EndCopy`, which passes the same success/failure
  // boolean it also provides to `EndCopy`, so we're not likely to accidentally
  // miss a failure by stubbing this method out.
  return NS_OK;

nsresult ExchangeMessageCopyHandler::OnCreateFinished(nsresult status,
                                                      nsIMsgDBHdr* newHdr) {
  // If we got an error, then there's no guarantee that we have a header.
  if (NS_FAILED(status)) {
    return OnCopyCompleted(status);
  }

  // If we got a successful response then the new header should be present.
  NS_ENSURE_TRUE(newHdr, NS_ERROR_UNEXPECTED);

if (mIsMove) {
  RefPtr<nsIMsgDBHdr> curHdr = mHeaders[mCurIndex];
  // It's a bit weird that we pass `nullptr` as the `listener` argument
  // (type `nsIMsgCopyServiceListener`), considering we're in the middle
  // of a copy. It looks like this argument is almost never set (and never
  // during a copy), except for `AttachmentDeleter::DeleteOriginalMessage`
  // which doesn't seem to do anything when the listener is called.
  MOZ_TRY(mSrcFolder.value()->DeleteMessages({curHdr}, mWindow, true, true,
                                             nullptr, false));
}

mCurIndex++;
if (mCurIndex == mHeaders.Length()) {
  // We've reached the end of our queue.
  return OnCopyCompleted(NS_OK);
}

return StartCopyingNextMessage();

NS_IMETHOD OnRemoteCreateFinished(nsresult status,
                                  nsACString const& serverId) override {
  if (NS_FAILED(status)) {
    mOnComplete(status, nullptr);
    return NS_OK;
  }
  // Using helper function to ease error handling.
  auto result = LocalCreateHelper(serverId);
  if (result.isErr()) {
    // NOTE: if the local creation fails, then we're left with the
    // one on the server and no attempt will be made to roll that back.
    // But that's _probably_ the Right Thing (tm) to do...
    nsresult rv = result.unwrapErr();
    mOnComplete(rv, nullptr);
    return rv;
  }

  mOnComplete(NS_OK, result.unwrap().get());
  return NS_OK;

// Add to DB and commit.
nsCOMPtr<nsIMsgDBHdr> liveHdr;
MOZ_TRY(db->AttachHdr(tmpHdr, true, getter_AddRefs(liveHdr)));
MOZ_TRY(db->Commit(nsMsgDBCommitType::kLargeCommit));

// Now write the full message to local message store.
// Ignore failures here - the operation has been successful and the new
// message is in the DB. Let the standard offline sync code deal with it.
//
// TODO: check offline-storage policy here! See
// https://bugzilla.mozilla.org/show_bug.cgi?id=2026215
nsresult rv = LocalCopyOfflineMessageContent(mFolder, msgStream, liveHdr);
if (NS_FAILED(rv)) {
  MOZ_LOG_FMT(
      gExchangeLog, mozilla::LogLevel::Warning,
      "MessageCreateHandler - failed writing offline copy (serverId={})",
      serverId);
}

return liveHdr;
